-- Tables defined in the codebase but not yet present on the live database
-- (ezyro_41282324_pdslive, dumped 2026-08-15). Generated by diffing every
-- CREATE TABLE in website/ and desktop-sync-api.php against that dump.
-- Safe to run as-is (IF NOT EXISTS everywhere) -- no data, structure only.
--
-- savings_loans / savings_credit_cards / savings_lent_money: new Savings
-- Tracker categories added on the desktop app this session (see
-- desktop-sync-api.php's ensureSavingsTables()) -- required for those
-- categories to sync between the desktop app and this site.
--
-- scheduled_notifications / notification_templates: the in-app/email
-- reminder + template feature (includes/notifications_helper.php,
-- reminders.php, notification-templates.php, cron-send-notifications.php)
-- normally self-creates these on first use, but they haven't been touched
-- live yet. Not to be confused with `reminders`/`reminder_templates`,
-- which already exist live and back the separate WhatsApp reminder feature.
--
-- NOT included: custom_field_modules (website/sql/migrate_field_reuse.sql)
-- -- an unused, unadopted migration; nothing in the codebase reads or
-- writes that table, so creating it would just be dead weight.

CREATE TABLE IF NOT EXISTS savings_loans (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    loan_type VARCHAR(30) NULL,
    lender VARCHAR(150) NOT NULL,
    account_no VARCHAR(100) NULL,
    interest_rate DECIMAL(6,3) NULL,
    emi_amount DECIMAL(14,2) NULL,
    tenure_months INT NULL,
    start_date DATE NULL,
    opening_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
    outstanding_balance DECIMAL(14,2) NOT NULL DEFAULT 0,
    notes TEXT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_user (user_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS savings_credit_cards (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    card_name VARCHAR(150) NOT NULL,
    bank VARCHAR(150) NULL,
    card_number_last4 VARCHAR(10) NULL,
    credit_limit DECIMAL(14,2) NULL,
    billing_day INT NULL,
    due_day INT NULL,
    opening_balance DECIMAL(14,2) NOT NULL DEFAULT 0,
    used_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
    notes TEXT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_user (user_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS savings_lent_money (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    borrower_name VARCHAR(150) NOT NULL,
    source_type VARCHAR(30) NULL,
    contact_info VARCHAR(150) NULL,
    interest_rate DECIMAL(6,3) NULL,
    date_lent DATE NULL,
    expected_return_date DATE NULL,
    opening_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
    outstanding_amount DECIMAL(14,2) NOT NULL DEFAULT 0,
    notes TEXT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_user (user_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notification_templates (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    name VARCHAR(150) NOT NULL,
    linked_to VARCHAR(50) NOT NULL COMMENT 'Module/folder this template belongs to, same values as custom_fields.linked_to',
    title VARCHAR(200) NOT NULL COMMENT 'May contain {placeholder} tokens',
    body TEXT NOT NULL COMMENT 'May contain {placeholder} tokens',
    channel_inapp TINYINT(1) NOT NULL DEFAULT 1,
    channel_email TINYINT(1) NOT NULL DEFAULT 1,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    INDEX idx_module (user_id, linked_to)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Includes template_id from creation (rather than as a later self-heal
-- ALTER, which is only needed for installs that already had this table
-- without the column) since this file is creating it fresh.
CREATE TABLE IF NOT EXISTS scheduled_notifications (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    title VARCHAR(200) NOT NULL,
    message TEXT NOT NULL,
    linked_to VARCHAR(50) DEFAULT NULL COMMENT 'Optional related module tag',
    custom_field_id INT DEFAULT NULL COMMENT 'Set when created via the reminder custom field type',
    record_id INT DEFAULT NULL COMMENT 'The record this reminder belongs to, for field-type reminders',
    block_instance INT NOT NULL DEFAULT 0 COMMENT 'Repeatable block instance index, for field-type reminders',
    template_id INT DEFAULT NULL,
    channel_inapp TINYINT(1) NOT NULL DEFAULT 1,
    channel_email TINYINT(1) NOT NULL DEFAULT 1,
    send_at DATETIME NOT NULL,
    repeat_type ENUM('none','daily','weekly','monthly','yearly') NOT NULL DEFAULT 'none',
    repeat_until DATE DEFAULT NULL,
    status ENUM('pending','sent','cancelled') NOT NULL DEFAULT 'pending',
    last_sent_at DATETIME DEFAULT NULL,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    INDEX idx_due (is_active, send_at),
    INDEX idx_field_record (custom_field_id, record_id, block_instance)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
